SELECT quantity_bucket, store_id, max_quantity, inventory_count FROM (SELECT CASE WHEN quantity >= 217 THEN 'high' WHEN quantity >= 72 THEN 'mid' ELSE 'low' END AS quantity_bucket, store_id, MAX(quantity) AS max_quantity, COUNT(*) AS inventory_count FROM inventory WHERE product_id = 4 GROUP BY CASE WHEN quantity >= 217 THEN 'high' WHEN quantity >= 72 THEN 'mid' ELSE 'low' END, store_id) AS t WHERE max_quantity >= 230 ORDER BY quantity_bucket DESC, store_id LIMIT 10
